const SEMANTIC_UNITS=new Map(Object.entries(SEMANTIC_UNIT_GROUPS).flatMap(([u,ids])=>ids.map(id=>[id,u])));
function semanticUnits(files){let count=0;for(const file of files)for(const f of file.fields){const expected=SEMANTIC_UNITS.get(f.id);check(expected!==undefined,file.path,f.path,f.id,'SEMANTIC_FIELD_ID');check(f.unit===expected,file.path,f.path,f.unit,'UNIT_SEMANTICS');count++;}return count;}
const DEATH_EFFECTS=[['shambler','FX-08','character.death'],['runner','FX-08','character.death'],['brute','FX-08','character.death'],['armored','FX-08','character.death'],['spitter','FX-08','character.death'],['archer','FX-08','character.death'],['bloater','FX-07','bloater.burst']];
function semanticEffects(docs){const effects=read(BASE+'packs/effects-portals.json');for(const [i,[id,required,effectId]]of DEATH_EFFECTS.entries()){const a=docs.zombies.archetypes[i],actual=effects.effects.find(e=>e.id===effectId);check(a.archetypeId===id&&a.deathEffect===required&&actual?.obligation===required,BASE+'config/zombies.json','/archetypes/'+i+'/deathEffect',a.deathEffect,'EFFECT_SEMANTICS');}return 7;}
function semanticStain(p){const i=p.effects.profiles.findIndex(e=>e.effectId==='bloater.stain');check(i>=0&&p.effects.profiles[i].durationSeconds===20,BASE+'config/presentation.json','/effects/profiles/'+i+'/durationSeconds',i<0?'missing':p.effects.profiles[i].durationSeconds,'STAIN_LIFETIME');return 20;}
Object.assign(module.exports,{SEMANTIC_UNIT_GROUPS,SEMANTIC_UNITS,semanticUnits,DEATH_EFFECTS,semanticEffects,semanticStain});
